package com.andye.warmod.antiair;import com.andye.warmod.warhead.WarheadPayloadType;import java.util.Optional;public record InterceptionResult(boolean success,Optional<WarheadPayloadType> payloadType){public static InterceptionResult failed(){return new InterceptionResult(false,Optional.empty());}public static InterceptionResult success(WarheadPayloadType p){return new InterceptionResult(true,Optional.of(p));}}